-- Freelance document number (وثيقة العمل الحر), printed in the company block and on the stamp.
ALTER TABLE store_invoice_settings ADD COLUMN freelance_no VARCHAR(40) NULL AFTER cr_number;

UPDATE store_invoice_settings t JOIN stores s ON s.id = t.store_id
SET t.freelance_no = 'FL-464627221'
WHERE s.name = 'DEXEL' AND t.freelance_no IS NULL;

UPDATE store_invoice_settings t JOIN stores s ON s.id = t.store_id
SET t.freelance_no = 'FL-7054846073'
WHERE s.name = 'ARTXEL' AND t.freelance_no IS NULL;

-- Stamps now carry the freelance document number. Only replaces the stamps seeded by 005, never an uploaded one.
UPDATE store_invoice_settings t JOIN stores s ON s.id = t.store_id
SET t.seal = 'data:image/svg+xml;base64,'
WHERE s.name = 'DEXEL' AND t.seal = 'data:image/svg+xml;base64,';

UPDATE store_invoice_settings t JOIN stores s ON s.id = t.store_id
SET t.seal = 'data:image/svg+xml;base64,'
WHERE s.name = 'ARTXEL' AND t.seal = 'data:image/svg+xml;base64,';
